import path from "node:path";
import { createClient } from "@libsql/client";
import { drizzle } from "drizzle-orm/libsql";
import { migrate } from "drizzle-orm/libsql/migrator";
import { errAsync, ResultAsync } from "neverthrow";
import type { Db } from "@/infra/db/db";
import { type DbError, dbFailure } from "@/infra/db/dbError";
import { seedIfEmpty } from "@/infra/db/seed";
import * as tables from "@/infra/db/tables";

export { DEFAULT_DATABASE_URL, databaseUrl, getDb, migrateDb, openDb };

const DEFAULT_DATABASE_URL = "file:data/trivia.db";

/** Versioned SQL migrations generated by drizzle-kit (see `drizzle.config.ts`). */
const MIGRATIONS_FOLDER: string = path.join(process.cwd(), "drizzle");

function databaseUrl(): string {
  return process.env.DATABASE_URL ?? DEFAULT_DATABASE_URL;
}

/** Applies pending migrations from `drizzle/` (idempotent: already applied ones are skipped). */
function migrateDb(db: Db): ResultAsync<Db, DbError> {
  return ResultAsync.fromPromise(migrate(db, { migrationsFolder: MIGRATIONS_FOLDER }), dbFailure).map((): Db => db);
}

/** Opens a database without touching its schema. */
function connect(url: string): Db {
  return drizzle(createClient({ url }), { schema: tables });
}

/** Opens a database and applies pending migrations. Used by scripts, tests and the dev server. */
function openDb(url: string): ResultAsync<Db, DbError> {
  return migrateDb(connect(url));
}

/** Production expects `npm run db:migrate` as a release step; elsewhere migrations run on startup. */
function openAppDb(url: string): ResultAsync<Db, DbError> {
  return process.env.NODE_ENV === "production"
    ? ResultAsync.fromSafePromise(Promise.resolve(connect(url)))
    : openDb(url);
}

const globalForDb = globalThis as typeof globalThis & {
  __triviaDb?: ResultAsync<Db, DbError>;
};

/** Process-wide database (kept on globalThis so Next dev hot reloads reuse it). Seeds example data once. */
function getDb(): ResultAsync<Db, DbError> {
  const cached = globalForDb.__triviaDb;
  if (cached !== undefined) return cached;
  const opened = openAppDb(databaseUrl())
    .andThen((db) => seedIfEmpty(db, new Date()).map((): Db => db))
    .orElse((error) => {
      // Do not cache failures: the next request retries.
      delete globalForDb.__triviaDb;
      return errAsync(error);
    });
  globalForDb.__triviaDb = opened;
  return opened;
}
